#ifndef __CST_H__
#define __CST_H__

#include <config.h>
#include <TYPES.H>

 /* ==================================================================
  *  Architecture-detection and pointer-width address type
  * ================================================================== */

  /*
   * Detect architecture from MSVC predefined macros.
   *
   *   _M_IX86   : x86-32 (defined to 600 or similar)
   *   _M_AMD64  : x86-64 (defined when targeting x64)
   *   _M_X64    : same as _M_AMD64, but some MSVC versions use this
   *
   * For x86 we keep 32-bit DWORD for addresses (matches the rest of
   * the kernel).  For x64 we widen to 64-bit unsigned.
   */
#if defined(_M_AMD64) || defined(_M_X64)
typedef unsigned long long  __ADDR_T;
#define __STACKTRACE_ARCH_X64   1
#define __ADDR_FMT              "%016llX"
#elif defined(_M_IX86) || defined(__I386__)
typedef unsigned long       __ADDR_T;
#define __STACKTRACE_ARCH_X86   1
#define __ADDR_FMT              "0x%08X "
#else
#error "stacktrace.h: unsupported target architecture"
#endif

   /* ==================================================================
	*  Per-architecture stack frame offsets
	*
	*  On x86: [EBP+4] = retaddr, [EBP+0] = saved EBP
	*  On x64: [RBP+8] = retaddr, [RBP+0] = saved RBP
	*
	*  These are also the widths of each stored value (4 vs 8 bytes),
	*  so we can use them as stepping constants.
	* ================================================================== */

#if defined(__STACKTRACE_ARCH_X86)
#define STACKTRACE_RETADDR_OFFSET   ((__ADDR_T)4)
#define STACKTRACE_FRAME_ALIGN      ((__ADDR_T)4)
#define STACKTRACE_SENTINEL_FRAME   ((__ADDR_T)0x00000000)
#elif defined(__STACKTRACE_ARCH_X64)
#define STACKTRACE_RETADDR_OFFSET   ((__ADDR_T)8)
#define STACKTRACE_FRAME_ALIGN      ((__ADDR_T)16)  /* x64 ABI stack aligned to 16 */
#define STACKTRACE_SENTINEL_FRAME   ((__ADDR_T)0x0000000000000000)
#endif

	/* ==================================================================
	 *  Constants
	 * ================================================================== */

	 /* Maximum stack frames to capture (safety limit ¡ª prevents infinite
	  * loops on corrupted stacks).  32 is more than enough for any
	  * reasonable kernel call chain. */
#define STACKTRACE_MAX_DEPTH    32

	  /* ==================================================================
	   *  Data structures (64-bit-ready: fields are __ADDR_T, not DWORD)
	   * ================================================================== */

	   /* One captured stack frame. */
typedef struct tag__STACK_FRAME {
	__ADDR_T    FrameAddr;      /* Frame-pointer value (EBP/RBP) for this frame  */
	__ADDR_T    ReturnAddr;     /* Return address (EIP/RIP) at this frame         */
} __STACK_FRAME;

/* A complete captured call stack. */
typedef struct tag__CALL_STACK {
	unsigned long FrameCount;                             /* Number of valid frames */
	__STACK_FRAME Frames[STACKTRACE_MAX_DEPTH];           /* Frame array, index 0 = innermost */
} __CALL_STACK;

/* ==================================================================
 *  Public API
 * ================================================================== */

 /*
  * Capture the current call stack.
  *
  * Parameters:
  *   pCallStack    - [out] Pre-allocated __CALL_STACK to fill.
  *   InitialFrame  - Starting frame-pointer value, or 0 to use current.
  *   InitialEip    - Starting instruction pointer, or 0 to use caller's.
  *
  * Returns:
  *   Number of valid frames captured (0 if the stack appears corrupt).
  *
  * Usage from BUG context:
  *   __CALL_STACK cs;
  *   GetCallStack(&cs, 0, 0);
  *   PrintCallStack(&cs);
  */
DWORD GetCallStack(
	__CALL_STACK*   pCallStack,
	__ADDR_T        InitialFrame,
	__ADDR_T        InitialEip
);

/*
 * Print a captured call stack to the kernel console.
 *
 * For each frame, prints:
 *   #NN  <return_address_hex>
 *
 * The user resolves addresses offline:
 *   dumpbin /disasm kernel.exe | findstr <address>
 *   -- or --
 *   addr2line -e kernel.elf -f <address>
 */
VOID PrintCallStack(const __CALL_STACK* pCallStack);

/*
 * Convenience: capture AND print the current call stack.
 * This is the primary function called from __BUG().
 */
VOID DumpCallStack(void);

#endif //__CST_H__
